def traced(topology, counters, demands, routes, settings):
    flows = topology.flows; total=len(flows); trials=settings.trials; eps=settings.epsilon; seed=settings.seed
    predictions, routed = compute_predictions(topology, demands, routes)
    pools=[]; ends=[]
    for flow in flows:
        entries=[]
        for attr in ('src_key','dst_key'):
            key = getattr(topology, attr).get(flow)
            if key is not None:
                v = counters.get(key)
                if v is not None: entries.append(v)
        if routed:
            v = predictions[flow]; c = topology.flow_cap[flow]
            entries.append(v if v <= c else c)
        pools.append(entries)
        s,t = flow; e=[]
        if s>=0: e.append((s,True))
        if t>=0: e.append((t,False))
        ends.append(e)
    samples=[]
    for index in range(total):
        pool = pools[index]; L=len(pool); s,t = flows[index]; per=[]
        for router,_o in ends[index]:
            if L==1: per.append([pool[0]]*trials)
            elif L==0: per.append([0]*trials)
            else: per.append([pool[scenario_weight(seed,router,tt,s,t)%L] for tt in range(trials)])
        samples.append(per)
    inc={r:[0]*trials for r in topology.node_ids}; out={r:[0]*trials for r in topology.node_ids}
    for index in range(total):
        for pos,(r,is_out) in enumerate(ends[index]):
            vs=samples[index][pos]; bkt = out[r] if is_out else inc[r]
            for tt in range(trials): bkt[tt]+=vs[tt]
    target = flows.index((61057,51547))
    print('POOL target', pools[target], 'ends', ends[target])
    def evidence(index, verbose=False):
        ent=[(v,trials) for v in pools[index]]
        cap = topology.flow_cap[flows[index]]
        for pos,(r,is_out) in enumerate(ends[index]):
            vs=samples[index][pos]; i=inc[r]; o=out[r]
            rem=[v+ii-oo for v,ii,oo in zip(vs,i,o)] if is_out else [v+oo-ii for v,ii,oo in zip(vs,i,o)]
            clamped=[item if 0 <= item <= cap else (0 if item < 0 else cap) for item in rem]
            rep,mass=band_of_values(clamped,eps)
            if verbose: print('  router',r,'out' if is_out else 'in','rawmax',max(rem),'rawmin',min(rem),'clamped rep',rep,'mass',mass)
            ent.append((rep,mass))
        res = select_band(ent,eps)
        if verbose: print('  entries', ent, '-> ', res)
        return res
    ev = evidence(target, verbose=True)
    # run the real greedy but only report the prefix evidence for the target
    flow_index = {f:i for i,f in enumerate(flows)}
    candidates=[0]*total; supports=[0]*total; heap=[]
    for index in range(total):
        v,m = evidence(index); candidates[index]=v; supports[index]=m
        heap.append((-m, flows[index]))
    heapify(heap)
    fixed=bytearray(total); settled=0
    while settled < total:
        while True:
            neg, f = heappop(heap); idx = flow_index[f]
            if fixed[idx] or supports[idx] != -neg: continue
            break
        value = candidates[idx]; fixed[idx]=1; settled+=1
        touched=set()
        for pos,(r,is_out) in enumerate(ends[idx]):
            vs=samples[idx][pos]; bkt = out[r] if is_out else inc[r]
            for tt in range(trials): bkt[tt]+= value - vs[tt]
            for other in topology.incident[r]:
                if not fixed[other]: touched.add(other)
        if target in touched and not fixed[target]:
            print('after fixing', f, 'value', value)
            evidence(target, verbose=True)
        for other in touched:
            fv,fm = evidence(other); candidates[other]=fv; supports[other]=fm
            heappush(heap, (-fm, flows[other]))
    return orig(topology, counters, demands, routes, settings)
